-- Version 12: credited pictures for the new history events and the two Kolkata women.
-- Freely licensed Wikimedia Commons images only (mostly paintings and photographs old enough to be public domain).
-- Left out: a modern illustration of Panna Dhai, a map that did not show the 1756 siege, and a famine photograph
-- of dying children, too distressing for a site used by school students.
-- Earlier migrations have already run on the live site; never edit them, add a new file instead.
UPDATE timeline_events e SET images = x.imgs FROM (VALUES
  ('udaipur', 'Chittor falls', '[{"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/1567-A_mine_explodes_during_the_siege_of_Chitor-right-Akbarnama-large.jpg/960px-1567-A_mine_explodes_during_the_siege_of_Chitor-right-Akbarnama-large.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "A mine explodes during the siege of Chittor, from the Akbarnama. Photo: Miskina and Mughal court artists, Public domain, via Wikimedia Commons"}]'::jsonb),
  ('udaipur', 'Peace with the Mughals', '[{"src": "https://upload.wikimedia.org/wikipedia/commons/9/93/Raja_Ravi_Varma%2C_Maharana_Amar_Singh_-_I.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled", "caption": "Maharana Amar Singh I, painted by Raja Ravi Varma. Photo: Raja Ravi Varma, Public domain, via Wikimedia Commons"}]'::jsonb),
  ('udaipur', 'A treaty with the Company', '[{"src": "https://upload.wikimedia.org/wikipedia/commons/5/54/In_mewar-state.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled", "caption": "Mewar on a map of India. Photo: Jolle, CC BY-SA 3.0, via Wikimedia Commons"}]'::jsonb),
  ('udaipur', 'Udaipur joins Rajasthan', '[{"src": "https://upload.wikimedia.org/wikipedia/commons/3/3a/Maharana_Bhupal_Singh.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled", "caption": "Maharana Bhupal Singh. Photo: Unknown author, Public domain, via Wikimedia Commons"}]'::jsonb),
  ('kolkata', 'The Battle of Plassey', '[{"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c4/Lord_Clive_meeting_with_Mir_Jafar_after_the_Battle_of_Plassey.jpg/960px-Lord_Clive_meeting_with_Mir_Jafar_after_the_Battle_of_Plassey.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Clive meets Mir Jafar after Plassey, painted by Francis Hayman. Photo: Francis Hayman, Public domain, via Wikimedia Commons"}]'::jsonb),
  ('kolkata', 'The Asiatic Society', '[{"src": "https://upload.wikimedia.org/wikipedia/commons/7/7d/Logo_of_the_Asiatic_Society_of_Bengal_in_1905_depicting_Sir_William_Jones.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled", "caption": "The Asiatic Society''s seal, with Sir William Jones. Photo: Unknown artist, Public domain, via Wikimedia Commons"}]'::jsonb),
  ('kolkata', 'Widows may remarry', '[{"src": "https://upload.wikimedia.org/wikipedia/commons/3/31/Ishwarchandra_Vidyasagar.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled", "caption": "Ishwar Chandra Vidyasagar. Photo: Unknown author, Public domain, via Wikimedia Commons"}]'::jsonb),
  ('kolkata', 'Bengal is split', '[{"src": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Pope1880BengalPres2.jpg/960px-Pope1880BengalPres2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "caption": "Bengal Presidency on an 1880 map. Photo: W. H. Allen and Co., Public domain, via Wikimedia Commons"}]'::jsonb)
) AS x(city, title, imgs) WHERE e.city_id = x.city AND e.title = x.title AND e.images = '[]'::jsonb;

UPDATE facts f SET image = x.img FROM (VALUES
  ('kolkata', 'Kadambini Ganguly', '{"src": "https://upload.wikimedia.org/wikipedia/commons/6/62/Kadambini_Ganguly.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled", "page": "https://commons.wikimedia.org/wiki/File:Kadambini_Ganguly.jpg", "credit": "Unknown author, Public domain, via Wikimedia Commons", "caption": "Kadambini Ganguly"}'::jsonb),
  ('kolkata', 'Begum Rokeya', '{"src": "https://upload.wikimedia.org/wikipedia/commons/7/76/Begum_Rokeya.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled", "page": "https://commons.wikimedia.org/wiki/File:Begum_Rokeya.jpg", "credit": "Unknown author, Public domain, via Wikimedia Commons", "caption": "Begum Rokeya"}'::jsonb)
) AS x(city, title, img), sections s WHERE s.id = f.section_id AND s.city_id = x.city AND f.title = x.title AND f.image IS NULL;
